var it = $input.first().json;
var q = it.query || {};
var TBL = { workers: "cbs_workers", incidents: "cbs_incidents", toolbox: "cbs_toolbox", hsmeet: "cbs_toolbox", training: "cbs_training", substances: "cbs_substances", rams: "cbs_rams", subbies: "cbs_subcontractors", subdocs: "cbs_sub_docs", insurance: "cbs_insurance", vehicles: "cbs_vehicles", checks: "cbs_vehicle_checks", crashes: "cbs_vehicle_accidents", photos: "cbs_photos", assets: "cbs_assets", services: "cbs_asset_services", requests: "cbs_requests", leave: "cbs_time_off", vservices: "cbs_vehicle_services", taskstat: "cbs_task_status", hazards: "cbs_hazards", increports: "cbs_incident_reports", materials: "cbs_materials", stockmoves: "cbs_stock_moves", ptmsheets: "cbs_ptm_sheets", claims: "cbs_claims", covertasks: "cbs_cover_tasks", companycerts: "cbs_company_certs", subjobs: "cbs_sub_jobdocs", cphsp: "cbs_cphsp", prestarts: "cbs_prestarts", hspolicy: "cbs_hs_policy", notifyrules: "cbs_notify_rules", suppliers: "cbs_suppliers", pos: "cbs_purchase_orders", signatures: "cbs_signatures", signons: "cbs_signons", jobplant: "cbs_job_plant", notices: "cbs_hub_notices", selectopts: "cbs_select_options", scaffinsp: "cbs_scaffold_insp", snags: "cbs_snags", programmes: "cbs_programmes", progitems: "cbs_prog_items", phototags: "cbs_photo_tags", jobtasks: "cbs_job_tasks", support: "cbs_support", variations: "cbs_variations", rfis: "cbs_rfis", jobrows: "cbs_jobs", jobcosts: "cbs_job_costs", scope: "cbs_scope", surveys: "cbs_surveys", signin: "cbs_signin", tbtopics: "cbs_tb_topics", ramstypes: "cbs_rams_types", cphspwording: "cbs_cphsp_wording" };
var a = String(q.a || "app").toLowerCase();
if (["list","save","del"].indexOf(a) === -1) { a = "app"; }
var tbl = TBL[String(q.t || "")] || "";
var internal = String(q.k || "") === "[redacted-internal-key]";
if (a !== "app" && !tbl) { throw new Error("Unknown register: " + q.t); }
/* Hub sign-in (PIN hashes and sign-in tokens): only CBS - Nav's sign-in service may read or write it (internal key). */
if (!internal && q.t === "signin") { throw new Error("Sign-in records are private"); }
if (!internal && a === "save" && (q.t === "taskstat" || q.t === "increports")) { throw new Error("This register is saved through its own builder"); }
if (!internal && a === "save" && q.t === "signons" && !(Number(q.id) > 0)) { throw new Error("Sign-ons are created on the signing page"); }
if (!internal && a === "save" && q.t === "notices" && !(Number(q.id) > 0)) { throw new Error("Notifications are created by the system"); }
if (!internal && a !== "list" && q.t === "jobplant") { throw new Error("The plant log is written from the Job File"); }
if (!internal && a === "save" && q.t === "snags") { throw new Error("Snags are saved from the snagging page"); }
if (!internal && a !== "list" && (q.t === "programmes" || q.t === "progitems")) { throw new Error("Programmes are edited from the Job File programme page"); }
if (!internal && a !== "list" && q.t === "support") { throw new Error("Feature requests and bug reports are saved from the Support page"); }
if (!internal && a !== "list" && (q.t === "variations" || q.t === "rfis" || q.t === "jobrows" || q.t === "jobcosts")) { throw new Error("Variations, RFIs and job records are saved from their own pages"); }
if (!internal && a !== "list" && q.t === "scope") { throw new Error("The scope of works is saved from the Scope of works page"); }
if (a !== "list" && q.t === "surveys") { throw new Error("Site surveys are saved from the survey form"); }
/* CPHSP wording: every row is a fixed part of the plan, so rows can be edited but not added or deleted from the hub */
if (!internal && q.t === "cphspwording" && (a === "del" || (a === "save" && !(Number(q.id) > 0)))) { throw new Error("CPHSP wording rows are fixed parts of the plan: edit the wording instead"); }
return [{ json: { route: a, tbl: tbl, rowId: Number(q.id || 0) || 0, query: q, body: it.body || {}, internal: internal, partial: String(q.partial || "") === "1" } }];

var q = $("Route").first().json.query || {};
var tbl = $("Route").first().json.tbl;
var rows = $input.all().map(function(i){ return i.json; }).filter(function(r){ return r && r.id; });
if (tbl === "cbs_photos") {
  if (!q.rt) { rows = []; }
  else { rows = rows.filter(function(r){ return String(r.ref_table) === String(q.rt) && String(r.ref_id) === String(q.rid); }); }
}
return [{ json: { rows: rows } }];

var r = $input.first().json;
var body = r.body || {};
var COLS = {
  cbs_workers: ["name","role","mobile","email","active","notes"],
  cbs_incidents: ["ref","occurred_at","kind","severity","person","location","sm8_job","description","immediate_action","injury_detail","treatment","notifiable","riddor_notified_at","investigation","root_cause","corrective_actions","action_owner","action_due","status","reported_by","closed_at","requires_investigation"],
  cbs_toolbox: ["meeting_type","held_on","topic","presenter","site","job_no","key_points","hazards_raised","actions","attendees","notes","pdf_url"],
  cbs_training: ["person","qualification","provider","issued_on","expires_on","reference","notes","docs_json","qual_other"],
  cbs_substances: ["product","supplier","location","coshh_class","quantity","use_for","sds_url","sds_date","controls","ppe","review_on","notes"],
  cbs_rams: ["site","activity","task","revision","prepared_by","dated","status","pdf_url","notes"],
  cbs_subcontractors: ["company","trade","job","contact","mobile","email","insurance_expiry","licence_type","licence_no","licence_expiry","rams_received","sds_provided","inducted","approved","notes"],
  cbs_sub_docs: ["company","item","custom_name","reference","issued_on","expires_on","doc_url","notes"],
  cbs_insurance: ["item","custom_name","insurer","policy_no","cover","starts_on","expires_on","doc_url","notes","cover_json"],
  cbs_vehicles: ["reg","make_model","year","assigned_to","tax_due","mot_expiry","ins_due","service_due","doc_url","notes"],
  cbs_vehicle_checks: ["vehicle","checked_on","checked_by","odometer","tyres_ok","lights_ok","fluids_ok","body_ok","first_aid_ok","extinguisher_ok","restraints_ok","defects","action","status","doc_url","reviewed"],
  cbs_vehicle_accidents: ["occurred_at","vehicle","driver","location","description","damage","injuries","third_party","third_party_reg","third_party_insurer","police_event_no","claim_no","status","doc_url","notes"],
  cbs_photos: ["ref_table","ref_id","caption","image","taken_by","taken_at"],
  cbs_assets: ["name","category","make_model","serial_no","asset_tag","location","assigned_to","purchased_on","service_interval","last_service","next_service","test_tag_due","status","notes"],
  cbs_asset_services: ["asset","serviced_on","serviced_by","work_done","cost","next_due","notes"],
  cbs_requests: ["requested_by","category","details","urgency","status","response","requested_at","closed_at"],
  cbs_time_off: ["worker","kind","from_date","to_date","part_day","days","notes","status","response","requested_at"],
  cbs_vehicle_services: ["vehicle","serviced_on","odometer","workshop","work_done","cost","next_due","next_due_km","receipt_url","notes"],
  cbs_hazards: ["hazard","activity","harm","likelihood","consequence","risk_rating","controls","control_level","residual_likelihood","residual_consequence","residual_risk","owner","last_reviewed","review_on","status","source","notes","rams_key","ctrl_codes","plant_categories"],
  cbs_materials: ["name","category","unit","location","qty_on_hand","min_level","reorder_qty","supplier","supplier_code","cost","sds_product","last_counted_on","last_counted_by","status","notes","sm8_uuid"],
  cbs_stock_moves: ["material_id","material","change","qty_after","reason","ref","by","at","notes"],
  cbs_ptm_sheets: ["sheet_date","job_no","site","client","job_desc","crew","vehicle","status","shortages","items_json","notes","pdf_url","prepared_by","loaded_by","loaded_at"],
  cbs_claims: ["claim_no","claim_type","direction","status","incident_date","lodged_on","policy","insurer","insurer_claim_no","other_party","other_contact","description","amount_claimed","excess","amount_settled","vehicle","asset","incident_ref","job_no","site","client","next_action","next_action_due","doc_url","closed_on","notes"],
  cbs_cover_tasks: ["cover","action","target","notes","status","raised_on","done_on"],
  cbs_company_certs: ["name","other_name","issuer","reference","level","issued_on","expires_on","cost","contact","docs_json","notes"],
  cbs_sub_jobdocs: ["company","job_no","site","client","start_date","doc_type","status","requested_on","received_on","reviewed_by","reviewed_on","docs_json","notes"],
  cbs_cphsp: ["cphsp_no","revision","dated","job_no","project","site","client","status","prepared_by","approved_by","approved_on","subs","subs_not_approved","pdf_url","state_json","notes"],
  cbs_prestarts: ["ps_no","held_on","held_at","job_no","site","client","site_lead","linked","docs_json","headcount","acknowledged","pdf_url","state_json","notes"],
  cbs_hs_policy: ["version","status","effective_on","review_due","approved_by","approver_role","approved_on","scope","commitment","objectives","notes","pdf_url"],
  cbs_notify_rules: ["event","label","post_note","tags","notes"],
  cbs_suppliers: ["name","contact","email","phone","account_no","address","notes"],
  cbs_purchase_orders: ["po_no","supplier","supplier_id","job_no","site","client","ordered_on","needed_by","deliver_to","status","lines_json","subtotal","vat","total","ordered_by","received_json","pdf_url","notes"],
  cbs_signatures: ["name","role","image","notes"],
  cbs_job_plant: ["job_no","asset_id","asset_name","asset_tag","category","out_with","booked_by","booked_at","due_back","returned_at","returned_by","source","notes"],
  cbs_select_options: ["reg","field","value","added_by"]
};
var BOOL = { active: true, notifiable: true, rams_received: true, sds_provided: true, inducted: true, approved: true, tyres_ok: true, lights_ok: true, fluids_ok: true, body_ok: true, first_aid_ok: true, extinguisher_ok: true, restraints_ok: true, reviewed: true };
var cols = COLS[r.tbl] || [];
var row = {};
cols.forEach(function(k){
  var v = body[k];
  if (BOOL[k]) { row[k] = v === true || v === "true"; }
  else { row[k] = v === undefined || v === null ? "" : String(v); }
});
return [{ json: row }];

var r = $('Route').first().json;
var row = $input.first().json;
if (r.tbl === 'cbs_assets') {
  var b = r.body || {};
  ['yard_status', 'out_job', 'out_with', 'out_since', 'due_back'].forEach(function(k){ row[k] = b[k] === undefined || b[k] === null ? '' : String(b[k]); });
}
if (r.tbl === 'cbs_subcontractors') {
  var sbb = r.body || {};
  delete row.rams_received; delete row.sds_provided;
  if (Object.prototype.hasOwnProperty.call(sbb, 'type')) { row.type = sbb.type === undefined || sbb.type === null ? '' : String(sbb.type); }
}
if (r.tbl === 'cbs_signons') {
  var sb = r.body || {};
  row = { reviewed: String(sb.reviewed) === 'Yes' ? 'Yes' : 'No' };
}
/* Team: site_lead = this person sees Run the site in the crew portal (start pre-start, toolbox talk, inspection, sub-contractor audit, load-ups).
   in_* = "Appears in" ticks: which name pickers this person is offered in (read by the shared cbs-people script). Only written when the save sends them.
   in_service = Appears in: Service sheets (offered under Signed / serviced on service sheets; also needs a saved signature). 27/10/2026.
   in_crew replaces portal_hide (the old opt-out): when in_crew is sent, portal_hide is kept as its opposite so crew pages that still read portal_hide stay in step.
   hub_signin = can sign in to the Operations Hub office pages (CBS - Nav sign-in).
   signature = the person's saved signature (PNG data URL, drawn on their Team record, 27/10/2026). Used for approvals and service sheets;
   CBS - Hub Data builds the signatures list from it. Only written when the save sends it; empty clears it. */
if (r.tbl === 'cbs_workers') {
  var wb = r.body || {};
  ['portal_hide','site_lead','hub_signin','in_crew','in_tasks','in_rams','in_coshh','in_cphsp','in_checks','in_toolbox','in_permits','in_incidents','in_po','in_survey','in_diary','in_docs','in_director','in_sm8','in_service'].forEach(function(k){
    if (Object.prototype.hasOwnProperty.call(wb, k)) { row[k] = wb[k] === true || wb[k] === 'true'; }
  });
  if (Object.prototype.hasOwnProperty.call(wb, 'in_crew')) { row.portal_hide = !row.in_crew; }
  if (Object.prototype.hasOwnProperty.call(wb, 'signature')) { var sv = wb.signature == null ? '' : String(wb.signature); row.signature = /^data:image\/(png|jpeg);base64,[A-Za-z0-9+\/=]+$/.test(sv) && sv.length < 400000 ? sv : ''; }
}
/* Hub sign-in records (internal key only): kind pin|session, name, pin_hash, token, device, created_at, last_seen, active ('1'/'0'). */
if (r.tbl === 'cbs_signin' && r.internal) {
  var sg = r.body || {};
  ['kind','name','pin_hash','token','device','created_at','last_seen','active'].forEach(function(k){ if (Object.prototype.hasOwnProperty.call(sg, k)) row[k] = sg[k] === null || sg[k] === undefined ? '' : String(sg[k]); });
}
return [{ json: row }];

var r = $('Route').first().json;
var row = $input.first().json;
var b = r.body || {};
function has(k){ return Object.prototype.hasOwnProperty.call(b, k); }
var EXTRA = {
  cbs_incidents: ['record_pdf_url'],
  cbs_incident_reports: ['incident_id','status','occurred_at','site','job_no','person','first_aid','corrective_action','update_hazard_register','review_hazard_register','hazard_register_done_on','riddor_required','investigate','signed_by','signed_on','pdf_url','report_json'],
  cbs_signons: ['doc_type','doc_id','doc_rev','doc_label','job_no','name','company','is_worker','signed_at','signature','reviewed','record_pdf_url','inducted_by'],
  /* load-up sheets: loaded_json = what the crew ticked when signing out, load_issues = problems reported by the crew, order_task_id = legacy */
  cbs_ptm_sheets: ['loaded_by','loaded_at','status','loaded_json','load_issues','order_task_id'],
  /* purchase orders: source (QuickBooks for uploaded QuickBooks POs), po_type (Material/Plant), hire_end + offhired_on (plant hire), qbo_po_id (QuickBooks PO number, so costing does not double-count) */
  cbs_purchase_orders: ['pdf_url','source','po_type','hire_end','offhired_on','qbo_po_id'],
  cbs_hub_notices: ['status','notes'],
  /* vehicles: fleet_only = Yes hides it from Kit and stock; no_monthly = Yes stops the monthly vehicle inspection task */
  cbs_vehicles: ['fleet_only','no_monthly'],
  /* scaffold inspections: every column is written here (no COLS entry in Clean Row) */
  cbs_scaffold_insp: ['job_no','site','inspected_on','inspector','company','cisrs_card','result','next_due','report_url','requested_by','requested_on','notes'],
  /* snags: written by CBS - Snagging only (internal key) */
  cbs_snags: ['job_no','snag_no','area','description','phase','assigned_to','due_on','status','before_json','after_json','raised_by','raised_at','pushed_at','pushed_by','fixed_by','fixed_at','fix_notes','signed_off_by','signed_off_at','history','notes'],
  /* programmes: written by CBS - Programme only (internal key) */
  cbs_programmes: ['job_no','status','created_by','created_at','closed_by','closed_at','skip_weekends','undo_json','history','notes'],
  /* programme items: checklist_json, pct and check_token are written by CBS - Task Checklist */
  cbs_prog_items: ['job_no','kind','parent_id','sort','name','start_on','end_on','status','assigned_to','blocked_by','notes','updated_by','updated_at','checklist_json','pct','check_token'],
  /* photo labels: ServiceM8 photo uuid -> phase + categories + caption, written from the Job File photo sorter */
  cbs_photo_tags: ['job_no','photo_uuid','phase_id','phase_name','categories','caption','updated_by','updated_at'],
  /* job task list items under each Job File requirement (req = requirement key, kind item|custom, files_json = uploaded PDFs/photos, freq + last_done = repeating inspections / toolbox talks) */
  cbs_job_tasks: ['job_no','req','kind','ref_id','ref_name','label','due_on','status','done_by','done_at','created_by','created_at','notes','files_json','freq','last_done'],
  /* support: feature requests (kind=feature) and bug reports (kind=bug), written by CBS - Support only (internal key) */
  cbs_support: ['kind','ref','title','details','expected','steps','section','priority','status','reason','response','duplicate_of','photos_json','page_url','device','raised_by','raised_at','updated_by','history'],
  /* variations: written by CBS - Variations only (internal key) */
  cbs_variations: ['job_no','var_no','title','description','instructed_by','instructed_on','instruction_via','cost','time_days','status','decided_by','decided_on','files_json','prog_item_ids','pdf_url','history','created_by','created_at'],
  /* RFIs: written by CBS - RFIs only (internal key) */
  cbs_rfis: ['job_no','rfi_no','subject','question','sent_to','sent_to_email','sent_on','needed_by','status','response','responded_on','files_json','pdf_url','history','created_by','created_at'],
  /* job costs: written by CBS - Job Costing only (internal key) */
  cbs_job_costs: ['job_no','cost_date','supplier','ref','category','description','net','vat','gross','po_no','source','qbo_id','file_url','notes','history','created_by','created_at'],
  /* job record: contract value, QuickBooks link and start date (planned start, kept in step with the programme by CBS - Programme) only (internal key) */
  cbs_jobs: ['contract_value','qbo_ref','starts_on']
};
/* number columns: blank saves as empty (null), anything else as a number */
var NUM = { cbs_prog_items: ['pct'], cbs_variations: ['cost','time_days'], cbs_jobs: ['contract_value'], cbs_job_costs: ['net','vat','gross'] };
var SYS = { cbs_hub_notices: ['title','message','event','job_no','sign','link','pdf','created_at'] };
if (r.internal && r.tbl === 'cbs_signons') { row = {}; }
if (r.partial) { var o = {}; Object.keys(row).forEach(function(k){ if (has(k)) o[k] = row[k]; }); row = o; }
if (r.internal || r.tbl !== 'cbs_signons') { (EXTRA[r.tbl] || []).forEach(function(k){ if (has(k)) row[k] = b[k] === null || b[k] === undefined ? '' : String(b[k]); }); }
if (r.internal) { (SYS[r.tbl] || []).forEach(function(k){ if (has(k)) row[k] = b[k] === null || b[k] === undefined ? '' : String(b[k]); }); }
(NUM[r.tbl] || []).forEach(function(k){ if (!Object.prototype.hasOwnProperty.call(row, k)) return; var v = String(row[k] == null ? '' : row[k]).trim(); row[k] = v === '' || isNaN(Number(v)) ? null : Number(v); });
return [{ json: row }];

try {
const r=$('Route').first().json; if(r.tbl!=='cbs_assets'||r.route!=='save') return [];
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim(),jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();
const id=Number($json.id)||Number(r.rowId)||0; if(!id) return [];
const b=r.body||{};
const A=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t=assets',body:{},json:true});
const a=(Array.isArray(A)?A:[]).find(x=>Number(x.id)===id); if(!a) return [];
let LG=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t=jobplant',body:{},json:true}); if(!Array.isArray(LG)) LG=[];
const save=(rid,row,p)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=jobplant&id='+(rid||0)+'&k='+K+(p?'&partial=1':''),body:row,json:true});
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const job=S(a.out_job), by=S(b._by)||S(b.by), src=S(b._source);
const open=LG.filter(o=>S(o.asset_id)===String(id)&&!S(o.returned_at));
for(const o of open){ if(jk(o.job_no)!==jk(job)){
  const note=job?'Moved to job '+job:(src||(/yard/i.test(S(a.yard_status))?'Returned to '+S(a.yard_status).toLowerCase():''));
  await save(o.id,{returned_at:now,returned_by:by||(job?'':'Yard team'),notes:[S(o.notes),note].filter(Boolean).join('; ')},true); } }
if(job){ const mine=open.filter(o=>jk(o.job_no)===jk(job));
  if(mine.length){ if(S(mine[0].out_with)!==S(a.out_with)||S(mine[0].due_back)!==S(a.due_back)) await save(mine[0].id,{out_with:S(a.out_with),due_back:S(a.due_back)},true); }
  else await save(0,{job_no:job,asset_id:String(id),asset_name:S(a.name),asset_tag:S(a.asset_tag),category:S(a.category),out_with:S(a.out_with),booked_by:by,booked_at:now,due_back:S(a.due_back),returned_at:'',returned_by:'',source:src||'Kit register',notes:''}); }
return [{json:{synced:true}}];
} catch(e){ return [{json:{syncError:String(e.message||e)}}]; }

var r=$('Route').first().json;var row=$input.first().json;
if(r.tbl==='cbs_stock_moves'){var b=r.body||{};
 if(b.location!==undefined)row.location=String(b.location==null?'':b.location);
 if(b.job_no!==undefined)row.job_no=String(b.job_no==null?'':b.job_no);
 if(!r.partial&&!r.rowId){
  if(!row.job_no){var m=String(row.ref||b.ref||'').match(/job\s*(?:no\.?)?\s*#?\s*([A-Za-z0-9-]+)/i);if(m)row.job_no=m[1];}
  if(!row.location&&row.material_id){try{var M=await this.helpers.httpRequest({method:'POST',url:'https://old-hub.example/webhook/cbs-admin-save?a=list&t=materials',body:{},json:true});var f=(Array.isArray(M)?M:[]).find(function(x){return String(x.id)===String(row.material_id);});if(f)row.location=String(f.location||'');}catch(e){}}
 }
}
return [{json:row}];

const r=$input.first().json;let sg=null;
if(r.tbl==='cbs_signons'&&r.rowId){try{const d=await this.helpers.httpRequest({url:'https://old-hub.example/webhook/cbs-admin-data?t=signons',json:true,timeout:15000});const x=((d&&d.signons)||[]).find(s=>Number(s.id)===Number(r.rowId));if(x)sg={doc:String(x.doc_type||''),id:String(x.doc_id||'')};}catch(e){}}
return [{json:Object.assign({},r,{_signon:sg})}];

/* Scope of works (cbs_scope): one row per job, written by CBS - Scope only (internal key). Columns pass straight through. */
var r = $('Route').first().json;
var row = $input.first().json;
if (r.tbl === 'cbs_scope' && r.internal) {
  var b = r.body || {};
  ['job_no','scope_json','history','created_by','created_at','updated_by','updated_at'].forEach(function(k){ if (Object.prototype.hasOwnProperty.call(b, k)) row[k] = b[k] === null || b[k] === undefined ? '' : String(b[k]); });
}
return [{ json: row }];

/* Vehicles: insp_freq = vehicle inspection frequency (Weekly / Monthly / Quarterly / Not required; blank = Monthly).
   insp_next = next inspection due (YYYY-MM-DD); the hub moves it on by the frequency as inspections are logged.
   Only written when the save sends them, so other vehicle saves never clear them. */
var r = $('Route').first().json;
var row = $input.first().json;
if (r.tbl === 'cbs_vehicles') {
  var b = r.body || {};
  ['insp_freq','insp_next'].forEach(function(k){ if (Object.prototype.hasOwnProperty.call(b, k)) { row[k] = b[k] === null || b[k] === undefined ? '' : String(b[k]); } });
}
/* Templates > Toolbox talk topics (cbs_tb_topics): read by the toolbox talk builder. points = one talking point per line.
